{
  "constraints": [
    {
      "constraint": "画面必须包含可识别为现代汽车（Hyundai）品牌的标识或品牌名称。",
      "polarity": "must_have",
      "variants": [],
      "source": "desc"
    },
    {
      "constraint": "现代品牌标识/名称的合法视觉形态域为：横向闭合椭圆外框内嵌明显倾斜H的图形标，或HYUNDAI/Hyundai文字标，或现代汽车中文文字标。",
      "polarity": "must_have",
      "variants": [
        "横向闭合椭圆斜H图形标",
        "HYUNDAI/Hyundai文字标",
        "现代汽车中文文字标"
      ],
      "source": "common_sense"
    },
    {
      "constraint": "图像不得呈现为其他汽车品牌标识的专属图形特征，如丰田三椭圆、大众VW、奔驰三叉星、宝马蓝白圆标、起亚或捷尼赛思标识。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "common_sense"
    },
    {
      "constraint": "图像不得以现代建筑、现代艺术、现代服饰、未来科技或现代时期等与汽车品牌无关的抽象时代意象作为主体来替代现代汽车品牌标识/名称。",
      "polarity": "must_not_have",
      "variants": [],
      "source": "desc"
    }
  ]
}
